(()=>{const e=document.querySelector("[data-year-progress]");if(!e)return;function t(){const t=new Date,n=t.getFullYear(),s=Date.UTC(n,0,1),o=(Date.UTC(n+1,0,1)-s)/864e5,i=(Date.UTC(n,t.getMonth(),t.getDate())-s)/864e5,r=(t.getHours()*3600+t.getMinutes()*60+t.getSeconds())/86400,a=(i+r)/o*100;e.querySelector("[data-progress-year]").textContent=n,e.querySelector("[data-progress-percent]").textContent=`${a.toFixed(1)}%`,e.querySelector("progress").value=a,e.querySelector("[data-progress-caption]").textContent=`已走过 ${i} 天 / 全年 ${o} 天`}t(),setInterval(t,6e4)})()